// BenchmarkLedgerSuite measures each callable of the suite of Ledger on
// ledgerIdle.
func BenchmarkLedgerSuite(b *testing.B) {
	b.Run("Run", func(b *testing.B) {
		ledgertest.BenchLedgerSuite(b, ledgertest.LedgerChecks.Run.Callable, ledgerIdle)
	})
	b.Run("Put", func(b *testing.B) {
		ledgertest.BenchLedgerSuite(b, ledgertest.LedgerChecks.Put.Callable, ledgerIdle)
	})
	b.Run("Get", func(b *testing.B) {
		ledgertest.BenchLedgerSuite(b, ledgertest.LedgerChecks.Get.Callable, ledgerIdle)
	})
}

